sql:
SELECT CustomerId, FirstName, LastName, Email
FROM Customer
WHERE Email IS NULL OR Email = '';

SELECT 
    (SELECT AVG(Total) FROM Invoice) AS average_total_per_invoice,
    (SELECT Name FROM Track 
     WHERE TrackId IN (
         SELECT TrackId FROM InvoiceLine 
         GROUP BY TrackId 
         SUM(UnitPrice * Quantity) DESC LIMIT 1
     )
    ) AS top_track_title;

SELECT *
FROM Customer
WHERE Phone LIKE '555%';

SELECT TrackId, Name
FROM Track
WHERE GenreId IS NULL;

SELECT COUNT(*) FROM Invoice
WHERE CustomerId IN (
    SELECT CustomerId FROM Customer WHERE Country = 'Brazil'
) AND InvoiceDate >= date('now', '-1 month') AND InvoiceDate < date('now', 'start of month');

SELECT COUNT(*) FROM InvoiceLine
JOIN Invoice ON InvoiceLine.InvoiceId = Invoice.InvoiceId
WHERE InvoiceDate >= '2010-01-01' AND InvoiceDate < '2010-04-01';

SELECT SUM(Total) 
FROM Invoice 
WHERE InvoiceDate >= '2009-01-01' AND InvoiceDate < '2010-01-01';

SELECT TrackId, Name, Milliseconds
FROM Track
WHERE Milliseconds <= 180000;

SELECT COUNT(*) 
FROM Invoice 
WHERE InvoiceDate >= '2023-01-01' AND InvoiceDate < '2024-01-01';

SELECT COUNT(DISTINCT CustomerId) 
FROM Invoice 
WHERE InvoiceDate BETWEEN '2013-01-01' AND '2013-12-31';
